--- a/src/ua_types_encoding_binary.c
+++ b/src/ua_types_encoding_binary.c
@@ -944,7 +944,17 @@

     if(encoding == UA_EXTENSIONOBJECT_ENCODED_BYTESTRING) {
         ret = ExtensionObject_decodeBinaryContent(dst, &binTypeId, ctx);
-        UA_NodeId_deleteMembers(&binTypeId);
+        if(dst->encoding == UA_EXTENSIONOBJECT_DECODED) {
+            /* The decoded content took ownership of no members from binTypeId. */
+            UA_NodeId_deleteMembers(&binTypeId);
+        } else if(ret != UA_STATUSCODE_GOOD) {
+            /* On error while decoding unknown encoded content, no ownership is
+             * transferred and we need to clean up binTypeId here. */
+            UA_NodeId_deleteMembers(&binTypeId);
+        } else {
+            /* Unknown type path: ownership of binTypeId was moved into
+             * dst->content.encoded.typeId. */
+        }
     } else if(encoding == UA_EXTENSIONOBJECT_ENCODED_NOBODY) {
         dst->encoding = (UA_ExtensionObjectEncoding)encoding;
         dst->content.encoded.typeId = binTypeId; /* move to dst */

